        .map_err(|e| ParliamentMemberRepoError::DatabaseError(e.to_string()))?
        .into_iter()
        .take_while(|r| {
            r.rank.unwrap_or_else(|| i64::from(req.max_entries() + 1))
                <= i64::from(req.max_entries())
        })
        .map(|r| {
            let member = ParliamentMember::new(
                r.name,
                r.parliament_member_id as u32,
                r.party_name,
